import { z } from "zod";

export const RepositoryContextSchema = z.object({
  id: z.string().min(1),
  name: z.string().min(1),
  root: z.string().min(1),
});

export type RepositoryContext = z.infer<typeof RepositoryContextSchema>;

export const BootstrapResponseSchema = z.object({
  repository: RepositoryContextSchema,
  checkpointSource: z.literal("pending"),
});

export type BootstrapResponse = z.infer<typeof BootstrapResponseSchema>;

export const ApiErrorSchema = z.object({
  error: z.object({
    code: z.string().min(1),
    message: z.string().min(1),
  }),
});

export type ApiError = z.infer<typeof ApiErrorSchema>;

---src/server/api.ts---
import { Router } from "express";

import type { AppConfig } from "./config.js";
import { resolveRepositoryContext } from "./repositoryContext.js";

export function createApiRouter(config: AppConfig): Router {
  const router = Router();

  router.get("/health", (_request, response) => {
    response.json({ status: "ok" });
  });

  router.get("/bootstrap", async (_request, response, next) => {
    try {
      const repository = await resolveRepositoryContext(config.repositoryRoot);
      response.json({ repository, checkpointSource: "pending" });
    } catch (error) {
      next(error);
    }
  });

  return router;
}

---src/server/config.ts---
import { z } from "zod";

const ConfigSchema = z.object({
  host: z.string().min(1),
  port: z.number().int().min(1).max(65_535),
  repositoryRoot: z.string().min(1),
  isProduction: z.boolean(),
});

export type AppConfig = z.infer<typeof ConfigSchema>;

export function loadConfig(): AppConfig {
  const parsedPort = Number(process.env.PORT ?? "8787");

  return ConfigSchema.parse({
    host: process.env.HOST ?? "127.0.0.1",
    port: parsedPort,
    repositoryRoot: process.env.REPOSITORY_ROOT || process.cwd(),
    isProduction: process.env.NODE_ENV === "production",
  });
}

---src/server/app.ts---
import { existsSync } from "node:fs";
import { resolve } from "node:path";

import express, { type ErrorRequestHandler } from "express";

import { createApiRouter } from "./api.js";
import type { AppConfig } from "./config.js";

export function createApp(config: AppConfig) {
  const app = express();

  app.disable("x-powered-by");
  app.use(express.json({ limit: "1mb" }));
  app.use("/api", createApiRouter(config));

  const clientDirectory = resolve(process.cwd(), "dist");
  if (config.isProduction && existsSync(clientDirectory)) {
    app.use(express.static(clientDirectory));
    app.use((_request, response) => {
      response.sendFile(resolve(clientDirectory, "index.html"));
    });
  }

  const errorHandler: ErrorRequestHandler = (error, _request, response, _next) => {
    const message = error instanceof Error ? error.message : "Unexpected server error.";
    response.status(500).json({
      error: {
        code: "INTERNAL_ERROR",
        message,
      },
    });
  };

  app.use(errorHandler);
  return app;
}

---src/server/repositoryContext.ts---
import { createHash } from "node:crypto";
import { realpath, stat } from "node:fs/promises";
import { basename, join } from "node:path";

import type { RepositoryContext } from "../shared/contracts.js";

export async function resolveRepositoryContext(root: string): Promise<RepositoryContext> {
  const resolvedRoot = await realpath(root);
  const gitEntry = await stat(join(resolvedRoot, ".git"));

  if (!gitEntry.isDirectory() && !gitEntry.isFile()) {
    throw new Error("Repository root does not contain a usable .git entry.");
  }

  return {
    id: createHash("sha256").update(resolvedRoot).digest("hex").slice(0, 16),
    name: basename(resolvedRoot),
    root: resolvedRoot,
  };
}

